{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Key Vault secret lacks a content type",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The database connection string secret does not specify content_type, making its intended format unclear to consumers retrieving it from Key Vault."
    },
    {
      "check_id": "CKV_AZURE_41",
      "title": "Key Vault secret lacks an expiration date",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret has no expiration_date and can therefore remain valid indefinitely, increasing exposure if the database credential is compromised."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name            = \"database-connection-string\"\n  value           = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id    = azurerm_key_vault.legal_keyvault.id\n  content_type    = \"SQL database connection string\"\n  expiration_date = \"2030-12-31T23:59:59Z\"\n  depends_on      = [azurerm_mssql_database.legal_metadata_db]\n}\n",
  "fix_summary": "Added a descriptive content type and an RFC 3339 expiration date to the Key Vault secret. All existing resource behavior and dependencies were retained."
}
